import{_ as i,C as t,o,c as s,E as a,a2 as d}from"./chunks/framework.BOeh4kYD.js";const c="/joinwell52/assets/verification-evidence-20260909/effect-and-delivery-figure.en.svg",f=JSON.parse('{"title":"The Action Finished, but Delivery Was Interrupted. Which Step Should Recovery Repeat?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"The Action Finished, but Delivery Was Interrupted. Which Step Should Recovery Repeat?","date":"2026-09-09","published_date":"2026-09-09","column":"open-source-engineering","category":"daily","article_type":"comparative-engineering-analysis","edition":"research-center","research_question":"The Action Finished, but Delivery Was Interrupted. Which Step Should Recovery Repeat?","summary":"A committed-wake experiment shows why recovery can acknowledge delivery without waking again—and why acknowledgment still does not prove every result was read.","cover":"/assets/verification-evidence-20260909/04-effect-and-delivery.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments; not independent QA; dependency substitutions disclosed","pageClass":"verification-evidence-article","sources":["https://github.com/paperclipai/paperclip/pull/13063"]},"headers":[],"relativePath":"en/engineering/2026-09-09-effect-and-delivery.md","filePath":"en/engineering/2026-09-09-effect-and-delivery.md","lastUpdated":1788930481000}'),l={name:"en/engineering/2026-09-09-effect-and-delivery.md"};function p(h,e,u,m,g,v){const n=t("ArticleCover"),r=t("ArticleTableScroll");return o(),s("div",null,[a(n,{image:"/assets/verification-evidence-20260909/04-effect-and-delivery.png",kicker:"Engineering · Experimental research",title:"The Action Finished, but Delivery Was Interrupted. Which Step Should Recovery Repeat?",summary:"A committed-wake experiment shows why recovery can acknowledge delivery without waking again—and why acknowledgment still does not prove every result was read.",version:"2026-09-09",languageHref:"/zh/engineering/2026-09-09-effect-and-delivery",languageLabel:"中文"}),a(r,{language:"en"}),e[0]||(e[0]=d('<h1 id="the-action-finished-but-delivery-was-interrupted-which-step-should-recovery-repeat" tabindex="-1">The Action Finished, but Delivery Was Interrupted. Which Step Should Recovery Repeat? <a class="header-anchor" href="#the-action-finished-but-delivery-was-interrupted-which-step-should-recovery-repeat" aria-label="Permalink to &quot;The Action Finished, but Delivery Was Interrupted. Which Step Should Recovery Repeat?&quot;">​</a></h1><p>An action has a recorded outcome. A continuation has been scheduled. The caller then loses its return before acknowledging delivery.</p><p>On recovery, should it repeat the action, wake the agent again, or merely finish the acknowledgment?</p><p>“Retries must be idempotent” is not yet an answer. Action completion, continuation scheduling, and delivery acknowledgment have different commit points. Recovery must identify which fact is missing.</p><h2 id="separate-lifetimes-connected-responsibility" tabindex="-1">Separate lifetimes, connected responsibility <a class="header-anchor" href="#separate-lifetimes-connected-responsibility" aria-label="Permalink to &quot;Separate lifetimes, connected responsibility&quot;">​</a></h2><p>Paperclip organizes agent work and governed tool access. Its merged <a href="https://github.com/paperclipai/paperclip/pull/13063" target="_blank" rel="noreferrer">PR #13063</a> connects task approvals, recorded outcomes, and continuation through durable delivery records. We studied the delivery service at <code>7a2314c7fc610e4ee28babcaddb5c87912166dd5</code>, not the entire approval product.</p><p>The valuable design is positive: an outcome can remain available after the originating run ends. Recovery can complete a missing delivery step without reenacting all earlier work.</p><p>The author&#39;s reported native approval journey used a local MCP fixture; live Notion remained unverified. We preserve that boundary rather than presenting fixture integration as universal provider acceptance.</p><h2 id="a-lost-return-after-commit" tabindex="-1">A lost return after commit <a class="header-anchor" href="#a-lost-return-after-commit" aria-label="Permalink to &quot;A lost return after commit&quot;">​</a></h2><p>Our harness loaded the complete original <code>toolActionDeliveryService</code> and supplied database-query and wakeup fixtures. The wakeup fixture first saved a committed record, then threw an exception.</p><p>The first delivery call stopped without acknowledgment. The second observed the committed wake, skipped a new wakeup call, and requested acknowledgment. Across both delivery attempts, wakeup was called once.</p><p>This is branch behavior under controlled persistence responses, not a database crash-recovery proof. We did not execute SQL, locks, or a process restart. Its value is narrower and concrete: the original service consults a committed fact instead of relying only on whether the previous call returned normally.</p><h2 id="six-controls" tabindex="-1">Six controls <a class="header-anchor" href="#six-controls" aria-label="Permalink to &quot;Six controls&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th style="text-align:right;">Wakeup calls</th><th>Acknowledgment observation</th></tr></thead><tbody><tr><td>Fresh delivery</td><td style="text-align:right;">1</td><td>One acknowledged</td></tr><tr><td>Committed wake already exists</td><td style="text-align:right;">0</td><td>One acknowledgment completed</td></tr><tr><td>Wakeup returns, but no committed row is found</td><td style="text-align:right;">1</td><td>No acknowledgment</td></tr><tr><td>Originating run remains active</td><td style="text-align:right;">0</td><td>Waits</td></tr><tr><td>Ten recorded outcomes</td><td style="text-align:right;">1</td><td>Eight inline; cutoff covers ten</td></tr><tr><td>Wake commits, throws, then delivery is retried</td><td style="text-align:right;">1 across both attempts</td><td>Second attempt acknowledges</td></tr></tbody></table><p><img src="'+c+'" alt="Figure: schematic of the saved observations discussed above. Arrows show the stated processing relationship, not a runtime screenshot. Source: accompanying experimental evidence."></p><p><em>Figure 1. schematic of the saved observations discussed above. Arrows show the stated processing relationship, not a runtime screenshot. Source: accompanying experimental evidence.</em></p><p>Two process runs agreed on all six cases. The source also scopes queries by task, company, and agent relationships, but our fixture does not evaluate SQL predicates. These results do not establish database isolation.</p><p>Our first two exploratory runs failed the normal-case assertion because the query fixture consumed a response while constructing an unexecuted subquery. Deferring consumption until the query was awaited fixed the harness. Upstream code did not change. Those failures are retained as experiment-development history, not Paperclip defects.</p><h2 id="acknowledged-does-not-mean-read" tabindex="-1">Acknowledged does not mean read <a class="header-anchor" href="#acknowledged-does-not-mean-read" aria-label="Permalink to &quot;Acknowledged does not mean read&quot;">​</a></h2><p>The ten-outcome control reveals a second distinction. The service inlines at most eight shortened results and includes a reference for the full set plus a committed cutoff. Acknowledgment can cover all ten referenced outcomes.</p><p>This controls context size and provides a recovery boundary. It does not prove that a new agent fetched the other two results, understood all ten, or completed the business task.</p><p>Reference delivery, content retrieval, and completed processing remain separate facts. If a product requires evidence that every omitted outcome was handled, that evidence must come from the continuation or acceptance layer.</p><h2 id="repeat-the-missing-step" tabindex="-1">Repeat the missing step <a class="header-anchor" href="#repeat-the-missing-step" aria-label="Permalink to &quot;Repeat the missing step&quot;">​</a></h2><p>A bounded principle follows: when a trustworthy commit fact already exists, recovery should complete the missing step before repeating earlier work.</p><p>The premise matters. An unknown action outcome cannot become failure merely because a response is absent. A wakeup that returned cannot count as committed when no corresponding record is found.</p><p>This delivery service has no provider-execution callback; it consumes existing outcomes. Our experiment therefore does not prove exactly-once external effects. Those require the action side&#39;s own identity and reconciliation contract.</p><p>The <a href="https://joinwell52-ai.github.io/joinwell52/en/research/evidence/2026-09-09-verification-evidence" target="_blank" rel="noreferrer">evidence guide</a> includes observations and dependency substitutions. This is a reproducible design comparison, not authorization to build a new recovery platform in CodeFlowMu.</p><p>Long work continues not only because an agent remembers a conversation, but because the system can distinguish a step already supported by evidence from one still awaiting acknowledgment.</p>',28))])}const b=i(l,[["render",p]]);export{f as __pageData,b as default};
